        <div class="grp"><span class="lbl">${C(t.theme)}</span><div class="seg-ctl pop-theme" id="theme-pop" role="group" aria-label="${C(t.theme)}">
          <button data-theme-set="auto" title="${C(t.themeAuto)}" aria-label="${C(t.themeAuto)}">${f2.auto}</button><button data-theme-set="study" title="${C(t.themeStudy)}" aria-label="${C(t.themeStudy)}">${f2.moon}</button><button data-theme-set="daylight" title="${C(t.themeDaylight)}" aria-label="${C(t.themeDaylight)}">${f2.sun}</button><button data-theme-set="paper" title="${C(t.themePaper)}" aria-label="${C(t.themePaper)}">${f2.paper}</button></div></div>
